    "formulaAccTemplate": {
      "zh-CN": "黄字精准 = 65% +（白字精准 − 65%）÷ 抗性，白字 {white}% 满值 100%。",
      "en": "Yellow precision = 65% + (white precision − 65%) ÷ resistance; white caps at {white}% for 100%.",
      "es": "Precisión amarilla = 65% + (blanca − 65%) ÷ resistencia; la blanca llega a {white}% para el 100%.",
      "fr": "Précision jaune = 65 % + (précision blanche − 65 %) ÷ résistance ; le blanc plafonne à {white} % pour 100 %.",
      "zh-TW": "黃字精準 = 65% +（白字精準 − 65%）÷ 抗性，白字 {white}% 滿值 100%。"
    },
    "formulaCritTemplate": {
      "zh-CN": "黄字会心 = 白字会心 ÷ 抗性，白字 {white}% 满值 80%。",
      "en": "Yellow crit = white crit ÷ resistance; white caps at {white}% for 80%.",
      "es": "Crítico amarillo = blanco ÷ resistencia; el blanco llega a {white}% para el 80%.",
      "fr": "Critique jaune = critique blanc ÷ résistance ; le blanc plafonne à {white} % pour 80 %.",
      "zh-TW": "黃字會心 = 白字會心 ÷ 抗性，白字 {white}% 滿值 80%。"
    },
    "formulaIntTemplate": {
      "zh-CN": "黄字会意 = 白字会意 ÷ 抗性，白字 {white}% 满值 40%。",
      "en": "Yellow affinity = white affinity ÷ resistance; white caps at {white}% for 40%.",
      "es": "Afinidad amarilla = blanca ÷ resistencia; la blanca llega a {white}% para el 40%.",
      "fr": "Affinité jaune = affinité blanche ÷ résistance ; le blanc plafonne à {white} % pour 40 %.",
      "zh-TW": "黃字會意 = 白字會意 ÷ 抗性，白字 {white}% 滿值 40%。"
    },
    "formulaBarsTemplate": {
      "zh-CN": "差几条估算（按承音每条）：精准 {acc} / 会心 {crit} / 会意 {int}；敏补会心 ≈ +{minCrit}% 白字 / 条，势补会意 ≈ +{shiInt}% 白字 / 条。",
      "en": "Bars short (per resonance bar): precision {acc} / crit {crit} / affinity {int}; an Agility bar adds ≈ +{minCrit}% white crit, a Momentum bar ≈ +{shiInt}% white affinity.",
      "es": "Barras que faltan (por barra de resonancia): precisión {acc} / crítico {crit} / afinidad {int}; una barra de Agilidad da ≈ +{minCrit}% de crítico blanco y una de Ímpetu ≈ +{shiInt}% de afinidad blanca.",
      "fr": "Barres manquantes (par barre de résonance) : précision {acc} / critique {crit} / affinité {int} ; une barre d’Agilité ajoute ≈ +{minCrit} % de critique blanc, une d’Élan ≈ +{shiInt} % d’affinité blanche.",
      "zh-TW": "差幾條估算（按承音每條）：精準 {acc} / 會心 {crit} / 會意 {int}；敏補會心 ≈ +{minCrit}% 白字 / 條，勢補會意 ≈ +{shiInt}% 白字 / 條。"
    },
    "formulaBowTemplate": {
      "zh-CN": "弓（弓玦）加成计入白字：精准弓 白字精准 +{acc} / 会心弓 白字会心 +{crit} / 会意弓 白字会意 +{int}，再按抗性换算黄字。抗性 {res}（当前版本）。",
      "en": "Bow bonuses count into white values: precision bow +{acc} white precision / crit bow +{crit} white crit / affinity bow +{int} white affinity, then converted by resistance. Resistance {res} (current version).",
      "es": "Los bonos de arco cuentan en blanco: arco de precisión +{acc} / de crítico +{crit} / de afinidad +{int}, luego se convierten por resistencia. Resistencia {res} (versión actual).",
      "fr": "Les bonus d’arc comptent en blanc : arc de précision +{acc} / de critique +{crit} / d’affinité +{int}, puis convertis par la résistance. Résistance {res} (version actuelle).",
      "zh-TW": "弓（弓玦）加成計入白字：精準弓 白字精準 +{acc} / 會心弓 白字會心 +{crit} / 會意弓 白字會意 +{int}，再按抗性換算黃字。抗性 {res}（當前版本）。"
    },
    "formulaOrderText": {
      "zh-CN": "定流派 → 对配方 → 录装备。一键最优拼一版 → 看差缺清单补缺。精准先堆满 100%；会心 148% / 会意 74% 封顶，溢出换劲 / 势 / 增伤。两套拿不准，存方案比总分。",
      "en": "Pick a build → match the recipe → log your gear. Auto-combo a first version → fill gaps from the gap list. Cap precision at 100% first; crit 148% / affinity 74% are the ceilings — overflow goes to Power / Momentum / damage. Torn between two sets? Save both as builds and compare totals.",
      "es": "Elige escuela → sigue la receta → registra tu equipo. Arma una versión automática → completa con la lista de faltas. Precisión al 100% primero; crítico 148% / afinidad 74% son el techo. ¿Entre dos conjuntos? Guárdalos y compara totales.",
      "fr": "Choisissez une école → suivez la recette → enregistrez l’équipement. Composez une première version auto → comblez avec la liste des manques. Précision à 100 % d’abord ; critique 148 % / affinité 74 % sont les plafonds. Hésitant entre deux ensembles ? Enregistrez-les et comparez les totaux.",
      "zh-TW": "定流派 → 對配方 → 錄裝備。一鍵最優拼一版 → 看差缺清單補缺。精準先堆滿 100%；會心 148% / 會意 74% 封頂，溢出換勁 / 勢 / 增傷。兩套拿不準，存方案比總分。"
    },
